package com.ke.ticketsystemke.service;import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.entity.*;import com.ke.ticketsystemke.repository.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class WarrantyTrackerServiceTest{@Mock WarrantyClaimRepository claims;@Mock WarrantyReplacementRepository replacements;@Mock WarrantyAttachmentRepository attachments;@Mock WarrantyClaimEventRepository events;@Mock EmployeeRepository employees;@Mock AccessService access;@Mock WarrantyDocumentRequirementService documents;WarrantyTrackerService service;LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));
@BeforeEach void setup(){service=new WarrantyTrackerService(claims,replacements,attachments,events,employees,access,new WarrantyPendingActionCalculator(),documents);lenient().when(replacements.findByWarrantyClaim_IdInAndActiveTrue(any())).thenReturn(List.of());lenient().when(attachments.findActiveCategoriesByClaimIds(any())).thenReturn(List.of());lenient().when(events.findLastActivityByClaimIds(any())).thenReturn(List.of());lenient().when(employees.findByEmployeeIdLowercaseIn(any())).thenReturn(List.of());}
@Test void countsUseSharedViewSemantics(){WarrantyClaim complaint=claim(1,"KE-100","Asha");WarrantyClaim follow=claim(2,"KE-200","Bina");follow.setManufacturerComplaintNumber("C2");follow.setComplaintRegisteredDate(today.minusDays(2));follow.setNextFollowUpDate(today.minusDays(1));follow.setState(WarrantyClaimState.VISIT_PENDING);follow.setExpectedVisitDate(today.minusDays(1));WarrantyClaim rejected=claim(3,"KE-300","Chitra");rejected.setResult(WarrantyClaimResult.WARRANTY_REJECTED);rejected.setState(WarrantyClaimState.WARRANTY_REJECTED_AWAITING_DECISION);WarrantyClaim closed=claim(4,"KE-400","Deepa");closed.setActive(false);closed.setState(WarrantyClaimState.CLOSED);closed.setResult(WarrantyClaimResult.CUSTOMER_DID_NOT_PROCEED);when(claims.findAllForTracker()).thenReturn(List.of(complaint,follow,rejected,closed));when(documents.billRuleApplies(complaint)).thenReturn(true);Map<String,Long> c=service.counts(new WarrantyTrackerFilter(),"ADMIN");assertThat(c.get("ALL_ACTIVE")).isEqualTo(3);assertThat(c.get("FOLLOW_UP_DUE")).isEqualTo(1);assertThat(c.get("VISIT_OVERDUE")).isEqualTo(1);assertThat(c.get("DOCUMENTS_PENDING")).isEqualTo(1);assertThat(c.get("COMPLAINT_NOT_REGISTERED")).isEqualTo(2);assertThat(c.get("AWAITING_CUSTOMER_DECISION")).isEqualTo(1);assertThat(c.get("REJECTED")).isEqualTo(1);assertThat(c.get("CLOSED")).isEqualTo(1);}
@Test void searchPaginationAndDaysPendingAreDeterministic(){WarrantyClaim a=claim(1,"KE-ALPHA","Asha Patel"),b=claim(2,"KE-BETA","Bina");a.setManufacturerName("Samsung");a.setProductSerialNumber("SN-99");when(claims.findAllForTracker()).thenReturn(List.of(a,b));WarrantyTrackerFilter f=new WarrantyTrackerFilter();f.setSearch("asha");f.setSize(1);var page=service.list(f,"ADMIN");assertThat(page.totalElements()).isEqualTo(1);assertThat(page.content().getFirst().ticketNumber()).isEqualTo("KE-ALPHA");assertThat(page.content().getFirst().daysPending()).isGreaterThanOrEqualTo(4);}
@Test void permissionAndValidationAreEnforced(){WarrantyTrackerFilter f=new WarrantyTrackerFilter();f.setSize(101);assertThatThrownBy(()->service.list(f,"ADMIN")).hasMessageContaining("400");f.setSize(20);f.setSort("updatedAt desc");assertThatThrownBy(()->service.list(f,"ADMIN")).hasMessageContaining("400");verify(access,atLeastOnce()).requireAllowed("ADMIN",AccessKey.VIEW_WARRANTY_TRACKER);}
@Test void deniedTrackerPermissionStopsBeforeDataQuery(){doNothing().when(access).requireAllowed("TECH",AccessKey.VIEW_TICKETS);doThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Access denied")).when(access).requireAllowed("TECH",AccessKey.VIEW_WARRANTY_TRACKER);assertThatThrownBy(()->service.list(new WarrantyTrackerFilter(),"TECH")).hasMessageContaining("403");verifyNoInteractions(claims);}
private WarrantyClaim claim(long id,String number,String customer){Ticket t=new Ticket();t.setId(id);t.setTicketNumber(number);t.setCustomerName(customer);t.setMobileNumber("9999999999");t.setProductType("TV");t.setStatus(TicketStatus.IN_PROGRESS);WarrantyClaim c=new WarrantyClaim();ReflectionTestUtils.setField(c,"id",id);ReflectionTestUtils.setField(c,"createdAt",Instant.now().minus(5,java.time.temporal.ChronoUnit.DAYS));ReflectionTestUtils.setField(c,"updatedAt",Instant.now());ReflectionTestUtils.setField(c,"markedWarrantyAt",Instant.now().minus(5,java.time.temporal.ChronoUnit.DAYS));c.setTicket(t);c.setClaimSequence(1);c.setActive(true);c.setState(WarrantyClaimState.COMPLAINT_REQUIRED);c.setResult(WarrantyClaimResult.PENDING);c.setManufacturerName("LG");c.setModelNumber("M1");c.setWarrantyOwnerEmployeeId("OWNER");return c;}}
